-- Generated by prepare.mjs. Requires account rollout; no scheduler or sending activation.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $hocalist_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_function constant text := 'hocalist.account_command(text,text,jsonb)';
  v_receipt_function constant text := 'hocalist.receive_stripe_test_event(text,text,text,text,bigint,boolean)';
  v_roles constant text[] := ARRAY['anon', 'authenticated', 'service_role'];
  v_privileges constant text[] := ARRAY[
    'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'];
  -- Predicates are sourced from drafts 003 and compared after lowercasing,
  -- removing whitespace, the pg_get_expr "AS uid" alias and ::text casts.
  v_expected_membership_qual constant text :=
    '(user_id=(selectauth.uid()))';
  v_expected_profile_qual constant text :=
    '(exists(select1fromhocalist.membershipsmwhere((m.id=role_profiles.membership_id)and(m.user_id=(selectauth.uid()))and(m.status=''active''))))';
  v_expected_contact_qual constant text :=
    '((user_id=(selectauth.uid()))and(exists(select1fromhocalist.membershipsmwhere((m.user_id=(selectauth.uid()))and(m.status=''active'')))))';
  v_expected_memberships constant text[] := ARRAY[
    'id:uuid', 'user_id:uuid', 'role:text', 'status:text', 'revision:bigint',
    'created_at:timestamp with time zone', 'updated_at:timestamp with time zone'];
  v_expected_role_profiles constant text[] := ARRAY[
    'membership_id:uuid', 'display_name:text', 'area_label:text', 'profile_note:text',
    'preferred_meetup_type:text', 'service_radius_miles:integer', 'pickup_availability:text',
    'revision:bigint', 'created_at:timestamp with time zone', 'updated_at:timestamp with time zone'];
  v_expected_profile_contacts constant text[] := ARRAY[
    'user_id:uuid', 'phone:text', 'address_line1:text', 'address_line2:text', 'city:text',
    'region:text', 'postal_code:text', 'country_code:text', 'revision:bigint',
    'created_at:timestamp with time zone', 'updated_at:timestamp with time zone'];
  v_expected_receipts constant text[] := ARRAY[
    'user_id:uuid', 'operation:text', 'idempotency_key:text', 'request_hash:text',
    'result:jsonb', 'created_at:timestamp with time zone'];
  v_account_tables constant text[] := ARRAY[
    'memberships', 'role_profiles', 'profile_contacts'];
  v_preserved_relations constant text[] := ARRAY['profiles', 'stripe_test_inbox'];
  v_table text;
  v_role text;
  v_priv text;
  v_columns text[];
  v_policy record;
  v_norm text;
BEGIN
  FOREACH v_table IN ARRAY v_account_tables || ARRAY['command_receipts'] LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'missing table: ' || v_table);
    ELSIF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = ('hocalist.' || v_table)::regclass) THEN
      v_issues := array_append(v_issues, 'row level security disabled: ' || v_table);
    END IF;
  END LOOP;

  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.memberships'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_memberships THEN
    v_issues := array_append(v_issues, 'memberships columns differ from the adapter allowlist');
  END IF;
  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.role_profiles'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_role_profiles THEN
    v_issues := array_append(v_issues, 'role_profiles columns differ from the adapter allowlist');
  END IF;
  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.profile_contacts'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_profile_contacts THEN
    v_issues := array_append(v_issues, 'profile_contacts columns differ from the adapter allowlist');
  END IF;
  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.command_receipts'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_receipts THEN
    v_issues := array_append(v_issues, 'command_receipts columns differ from the reviewed shape');
  END IF;

  -- Policy set, attributes and full predicates. Name/role/command checks alone
  -- do not prove row isolation, so the normalized predicate is compared too.
  IF (SELECT count(*) FROM pg_policies
      WHERE schemaname = 'hocalist' AND tablename = ANY(v_account_tables)) <> 3 THEN
    v_issues := array_append(v_issues, 'unexpected account policy set');
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies
             WHERE schemaname = 'hocalist' AND tablename = ANY(v_preserved_relations)) THEN
    v_issues := array_append(v_issues, 'preserved baseline object gained a policy');
  END IF;
  FOR v_policy IN
    SELECT tablename, policyname, permissive, roles::text[] AS roles, cmd, qual, with_check
    FROM pg_policies
    WHERE schemaname = 'hocalist' AND tablename = ANY(v_account_tables)
  LOOP
    IF v_policy.policyname NOT IN (
      'membership_owner_read', 'active_owner_profile_read', 'active_owner_contact_read') THEN
      v_issues := array_append(v_issues, 'unexpected account policy: ' || v_policy.policyname);
      CONTINUE;
    END IF;
    IF v_policy.permissive <> 'PERMISSIVE'
       OR v_policy.cmd <> 'SELECT'
       OR v_policy.roles <> ARRAY['authenticated']
       OR v_policy.with_check IS NOT NULL THEN
      v_issues := array_append(v_issues, 'policy attributes changed: ' || v_policy.policyname);
    END IF;
    v_norm := regexp_replace(
      regexp_replace(
        regexp_replace(lower(coalesce(v_policy.qual, '')), '\s+', '', 'g'),
        'asuid', '', 'g'),
      '::text', '', 'g');
    IF v_policy.policyname = 'membership_owner_read'
       AND v_norm IS DISTINCT FROM v_expected_membership_qual THEN
      v_issues := array_append(v_issues, 'policy predicate changed: ' || v_policy.policyname);
    ELSIF v_policy.policyname = 'active_owner_profile_read'
       AND v_norm IS DISTINCT FROM v_expected_profile_qual THEN
      v_issues := array_append(v_issues, 'policy predicate changed: ' || v_policy.policyname);
    ELSIF v_policy.policyname = 'active_owner_contact_read'
       AND v_norm IS DISTINCT FROM v_expected_contact_qual THEN
      v_issues := array_append(v_issues, 'policy predicate changed: ' || v_policy.policyname);
    END IF;
  END LOOP;

  -- Account table ACLs: exactly authenticated SELECT without grant option,
  -- no column grants, and no effective privilege beyond that.
  FOREACH v_table IN ARRAY v_account_tables LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
      WHERE c.oid = ('hocalist.' || v_table)::regclass
        AND pg_get_userbyid(a.grantee) <> 'postgres'
        AND NOT (pg_get_userbyid(a.grantee) = 'authenticated'
                 AND a.privilege_type = 'SELECT' AND NOT a.is_grantable)
    ) THEN
      v_issues := array_append(v_issues,
        'hocalist.' || v_table || ' ACL differs from the reviewed authenticated SELECT grant');
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
      WHERE c.oid = ('hocalist.' || v_table)::regclass
        AND pg_get_userbyid(a.grantee) = 'authenticated'
        AND a.privilege_type = 'SELECT' AND NOT a.is_grantable
    ) THEN
      v_issues := array_append(v_issues,
        'authenticated is missing SELECT on hocalist.' || v_table);
    END IF;
    IF EXISTS (
      SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
      WHERE att.attrelid = ('hocalist.' || v_table)::regclass
        AND att.attnum > 0 AND NOT att.attisdropped
    ) THEN
      v_issues := array_append(v_issues,
        'hocalist.' || v_table || ' has unexpected column grants');
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      FOREACH v_priv IN ARRAY v_privileges LOOP
        IF has_table_privilege(v_role, 'hocalist.' || v_table, v_priv)
           IS DISTINCT FROM (v_role = 'authenticated' AND v_priv = 'SELECT') THEN
          v_issues := array_append(v_issues,
            'unexpected ' || v_priv || ' for ' || v_role || ' on hocalist.' || v_table);
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;

  -- Receipts: owner-only ACL, no column grants, no effective client access.
  IF EXISTS (
    SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
    WHERE c.oid = 'hocalist.command_receipts'::regclass
      AND pg_get_userbyid(a.grantee) <> 'postgres'
  ) THEN
    v_issues := array_append(v_issues, 'command_receipts has unexpected non-owner grants');
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
    WHERE att.attrelid = 'hocalist.command_receipts'::regclass
      AND att.attnum > 0 AND NOT att.attisdropped
  ) THEN
    v_issues := array_append(v_issues, 'command_receipts has unexpected column grants');
  END IF;
  FOREACH v_role IN ARRAY v_roles LOOP
    FOREACH v_priv IN ARRAY v_privileges LOOP
      IF has_table_privilege(v_role, 'hocalist.command_receipts', v_priv) THEN
        v_issues := array_append(v_issues,
          'unexpected ' || v_priv || ' for ' || v_role || ' on hocalist.command_receipts');
      END IF;
    END LOOP;
  END LOOP;

  -- account_command: exactly authenticated EXECUTE without grant option.
  IF EXISTS (
    SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
    WHERE p.oid = to_regprocedure(v_function)
      AND pg_get_userbyid(a.grantee) <> 'postgres'
      AND NOT (pg_get_userbyid(a.grantee) = 'authenticated'
               AND a.privilege_type = 'EXECUTE' AND NOT a.is_grantable)
  ) OR EXISTS (
    SELECT 1 FROM pg_proc p WHERE p.oid = to_regprocedure(v_function) AND p.proacl IS NULL
  ) THEN
    v_issues := array_append(v_issues,
      'account_command ACL differs from the reviewed authenticated EXECUTE grant');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
    WHERE p.oid = to_regprocedure(v_function)
      AND pg_get_userbyid(a.grantee) = 'authenticated'
      AND a.privilege_type = 'EXECUTE' AND NOT a.is_grantable
  ) THEN
    v_issues := array_append(v_issues, 'authenticated is missing EXECUTE on account_command');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p
    WHERE p.oid = to_regprocedure(v_function)
      AND p.prosecdef
      AND p.proconfig = ARRAY['search_path=""']
      AND pg_get_userbyid(p.proowner) = 'postgres'
  ) THEN
    v_issues := array_append(v_issues, 'account_command security properties changed');
  END IF;
  FOREACH v_role IN ARRAY v_roles LOOP
    IF has_function_privilege(v_role, v_function, 'EXECUTE')
       IS DISTINCT FROM (v_role = 'authenticated') THEN
      v_issues := array_append(v_issues,
        'unexpected EXECUTE for ' || v_role || ' on account_command');
    END IF;
  END LOOP;

  -- Schema: owner plus authenticated and service_role USAGE only.
  IF EXISTS (
    SELECT 1 FROM pg_namespace n, aclexplode(n.nspacl) a
    WHERE n.nspname = 'hocalist'
      AND NOT (
        pg_get_userbyid(a.grantee) = 'postgres'
        OR (pg_get_userbyid(a.grantee) IN ('authenticated', 'service_role')
            AND a.privilege_type = 'USAGE' AND NOT a.is_grantable)
      )
  ) THEN
    v_issues := array_append(v_issues,
      'hocalist schema ACL differs from the reviewed account grant set');
  END IF;
  IF NOT has_schema_privilege('authenticated', 'hocalist', 'USAGE')
     OR has_schema_privilege('authenticated', 'hocalist', 'CREATE')
     OR has_schema_privilege('anon', 'hocalist', 'USAGE')
     OR has_schema_privilege('anon', 'hocalist', 'CREATE')
     OR NOT has_schema_privilege('service_role', 'hocalist', 'USAGE')
     OR has_schema_privilege('service_role', 'hocalist', 'CREATE') THEN
    v_issues := array_append(v_issues, 'schema privileges are wrong after apply');
  END IF;

  -- Preserved baseline privilege matrix (same rules as the guard).
  FOREACH v_table IN ARRAY v_preserved_relations LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'preserved object missing: hocalist.' || v_table);
    ELSE
      IF EXISTS (
        SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
        WHERE c.oid = ('hocalist.' || v_table)::regclass
          AND pg_get_userbyid(a.grantee) <> 'postgres'
      ) THEN
        v_issues := array_append(v_issues,
          'hocalist.' || v_table || ' has unexpected non-owner grants');
      END IF;
      IF EXISTS (
        SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
        WHERE att.attrelid = ('hocalist.' || v_table)::regclass
          AND att.attnum > 0 AND NOT att.attisdropped
      ) THEN
        v_issues := array_append(v_issues,
          'hocalist.' || v_table || ' has unexpected column grants');
      END IF;
      IF EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'hocalist' AND tablename = v_table
      ) THEN
        v_issues := array_append(v_issues,
          'hocalist.' || v_table || ' has an unexpected policy');
      END IF;
      FOREACH v_role IN ARRAY v_roles LOOP
        FOREACH v_priv IN ARRAY v_privileges LOOP
          IF has_table_privilege(v_role, 'hocalist.' || v_table, v_priv) THEN
            v_issues := array_append(v_issues,
              'unexpected ' || v_priv || ' for ' || v_role || ' on hocalist.' || v_table);
          END IF;
        END LOOP;
      END LOOP;
    END IF;
  END LOOP;

  IF to_regprocedure(v_receipt_function) IS NULL THEN
    v_issues := array_append(v_issues, 'deployed 005 receive_stripe_test_event is missing');
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
      WHERE p.oid = to_regprocedure(v_receipt_function)
        AND NOT (
          pg_get_userbyid(a.grantee) = 'postgres'
          OR (pg_get_userbyid(a.grantee) = 'service_role'
              AND a.privilege_type = 'EXECUTE' AND NOT a.is_grantable)
        )
    ) THEN
      v_issues := array_append(v_issues,
        'receive_stripe_test_event ACL differs from the reviewed 005 state');
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      IF (v_role = 'service_role'
          AND NOT has_function_privilege(v_role, v_receipt_function, 'EXECUTE'))
         OR (v_role <> 'service_role'
          AND has_function_privilege(v_role, v_receipt_function, 'EXECUTE')) THEN
        v_issues := array_append(v_issues,
          'receive_stripe_test_event execution differs for ' || v_role);
      END IF;
    END LOOP;
  END IF;
  IF to_regprocedure('hocalist.handle_new_user()') IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
      WHERE p.oid = to_regprocedure('hocalist.handle_new_user()')
        AND pg_get_userbyid(a.grantee) <> 'postgres'
    ) THEN
      v_issues := array_append(v_issues, 'handle_new_user has unexpected execution grants');
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      IF has_function_privilege(v_role, 'hocalist.handle_new_user()', 'EXECUTE') THEN
        v_issues := array_append(v_issues,
          'unexpected EXECUTE for ' || v_role || ' on handle_new_user');
      END IF;
    END LOOP;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
    WHERE t.tgrelid = 'auth.users'::regclass
      AND t.tgname = 'on_auth_user_created'
      AND t.tgfoid = to_regprocedure('hocalist.handle_new_user()')
      AND t.tgenabled = 'O'
  ) THEN
    v_issues := array_append(v_issues, 'signup routing trigger changed');
  END IF;

  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist post-apply verification failed: %', array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_postapply$;
-- DRAFT. Requires reviewed/applied 003 and 005. No live migration permission implied.
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TABLE hocalist.stripe_test_plans (
 code text PRIMARY KEY CHECK(code IN ('pro','elite')),
 price_id text UNIQUE NOT NULL,
 amount_minor integer NOT NULL CHECK(amount_minor>0),
 currency text NOT NULL CHECK(currency='usd'),
 enabled boolean NOT NULL DEFAULT false
);
INSERT INTO hocalist.stripe_test_plans VALUES
 ('pro','price_1UHQfsDmHEV44E5Y7mV2Vd0T',1500,'usd',false),
 ('elite','price_1UHQgTDmHEV44E5YnvAxiHlH',3000,'usd',false);
CREATE TABLE hocalist.stripe_test_customers (
 membership_id uuid PRIMARY KEY REFERENCES hocalist.memberships(id),
 customer_id text UNIQUE NOT NULL CHECK(customer_id ~ '^cus_[A-Za-z0-9]+$'),
 requires_review boolean NOT NULL DEFAULT false
);
CREATE TABLE hocalist.stripe_test_checkouts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 membership_id uuid NOT NULL REFERENCES hocalist.memberships(id),
 request_key uuid NOT NULL,
 plan_code text NOT NULL REFERENCES hocalist.stripe_test_plans(code),
 price_id text NOT NULL,
 amount_minor integer NOT NULL,
 state text NOT NULL DEFAULT 'creating' CHECK(state IN ('creating','open','complete','expired')),
 session_id text UNIQUE,
 session_url text,
 created_at timestamptz NOT NULL DEFAULT now(),
 expires_at timestamptz NOT NULL DEFAULT (now()+interval '1 hour'),
 UNIQUE(membership_id,request_key)
);
CREATE UNIQUE INDEX stripe_test_one_checkout ON hocalist.stripe_test_checkouts(membership_id)
 WHERE state IN ('creating','open');
CREATE TABLE hocalist.stripe_test_subscriptions (
 membership_id uuid PRIMARY KEY REFERENCES hocalist.memberships(id),
 subscription_id text UNIQUE NOT NULL,
 plan_code text REFERENCES hocalist.stripe_test_plans(code),
 provider_status text NOT NULL,
 paid_until timestamptz,
 cancel_at_period_end boolean NOT NULL,
 requires_review boolean NOT NULL DEFAULT false,
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE hocalist.stripe_test_worker_lock (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 token uuid, event_id text, expires_at timestamptz
);
INSERT INTO hocalist.stripe_test_worker_lock(singleton) VALUES(true);
ALTER TABLE hocalist.stripe_test_inbox ADD COLUMN attempts integer NOT NULL DEFAULT 0,
 ADD COLUMN available_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN last_error text;
ALTER TABLE hocalist.stripe_test_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE hocalist.stripe_test_customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE hocalist.stripe_test_checkouts ENABLE ROW LEVEL SECURITY;
ALTER TABLE hocalist.stripe_test_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE hocalist.stripe_test_worker_lock ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.stripe_test_plans,hocalist.stripe_test_customers,
 hocalist.stripe_test_checkouts,hocalist.stripe_test_subscriptions,hocalist.stripe_test_worker_lock
 FROM PUBLIC,anon,authenticated,service_role;

-- Trusted server only. p_user must come from Supabase Auth /user, never request JSON.
CREATE FUNCTION hocalist.stripe_test_checkout_begin(p_user uuid,p_plan text,p_key uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m hocalist.memberships%ROWTYPE; c hocalist.stripe_test_checkouts%ROWTYPE;
 p hocalist.stripe_test_plans%ROWTYPE; customer text;
BEGIN
 PERFORM 1 FROM hocalist.profiles WHERE id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'billing_access_denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM hocalist.memberships WHERE user_id=p_user AND role='seller' FOR UPDATE;
 IF NOT FOUND OR m.status<>'active' OR EXISTS(SELECT 1 FROM hocalist.memberships WHERE user_id=p_user AND status IN ('restricted','disabled')) THEN
  RAISE EXCEPTION 'billing_access_denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM hocalist.stripe_test_plans WHERE code=p_plan AND enabled;
 IF NOT FOUND OR p_key IS NULL THEN RAISE EXCEPTION 'invalid_plan_or_key' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM hocalist.stripe_test_customers WHERE membership_id=m.id AND requires_review) THEN
  RAISE EXCEPTION 'billing_review_required' USING ERRCODE='P0001'; END IF;
 SELECT * INTO c FROM hocalist.stripe_test_checkouts WHERE membership_id=m.id AND request_key=p_key;
 IF FOUND AND c.plan_code<>p_plan THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
 IF FOUND AND c.state IN ('complete','expired') THEN RAISE EXCEPTION 'checkout_closed' USING ERRCODE='P0001'; END IF;
 IF EXISTS(SELECT 1 FROM hocalist.stripe_test_subscriptions WHERE membership_id=m.id AND (provider_status NOT IN ('canceled','incomplete_expired') OR requires_review)) THEN
  RAISE EXCEPTION 'subscription_exists' USING ERRCODE='P0001'; END IF;
 -- Never expire a session solely from our clock: it could have completed before expiry.
 IF c.id IS NULL THEN
  IF EXISTS(SELECT 1 FROM hocalist.stripe_test_checkouts WHERE membership_id=m.id AND state IN ('creating','open')) THEN
   RAISE EXCEPTION 'checkout_pending' USING ERRCODE='P0001'; END IF;
  INSERT INTO hocalist.stripe_test_checkouts(membership_id,request_key,plan_code,price_id,amount_minor)
   VALUES(m.id,p_key,p.code,p.price_id,p.amount_minor) RETURNING * INTO c;
 END IF;
 -- Beyond this window Stripe may no longer accept the original expires_at. Reconcile, never blindly create again.
 IF c.state='creating' AND c.created_at<now()-interval '25 minutes' THEN
  RAISE EXCEPTION 'checkout_reconciliation_required' USING ERRCODE='P0001'; END IF;
 SELECT customer_id INTO customer FROM hocalist.stripe_test_customers WHERE membership_id=m.id;
 RETURN jsonb_build_object('checkout_id',c.id,'membership_id',m.id,'customer_id',customer,
  'price_id',c.price_id,'amount_minor',c.amount_minor,'plan_code',c.plan_code,
  'session_id',c.session_id,'session_url',c.session_url,'expires_at',floor(extract(epoch FROM c.expires_at)), 'state',c.state);
END; $$;

CREATE FUNCTION hocalist.stripe_test_checkout_bind(p_checkout uuid,p_customer text,p_session text DEFAULT NULL,p_url text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c hocalist.stripe_test_checkouts%ROWTYPE; current_customer text;
BEGIN
 SELECT * INTO STRICT c FROM hocalist.stripe_test_checkouts WHERE id=p_checkout FOR UPDATE;
 IF c.state NOT IN ('creating','open') THEN RAISE EXCEPTION 'checkout_closed'; END IF;
 IF p_customer IS NULL OR p_customer !~ '^cus_[A-Za-z0-9]+$' THEN RAISE EXCEPTION 'invalid_customer'; END IF;
 INSERT INTO hocalist.stripe_test_customers(membership_id,customer_id) VALUES(c.membership_id,p_customer) ON CONFLICT(membership_id) DO NOTHING;
 SELECT customer_id INTO current_customer FROM hocalist.stripe_test_customers WHERE membership_id=c.membership_id;
 IF current_customer<>p_customer THEN RAISE EXCEPTION 'customer_conflict'; END IF;
 IF p_session IS NOT NULL THEN
  IF p_session !~ '^cs_test_[A-Za-z0-9]+$' OR p_url IS NULL OR p_url !~ '^https://checkout[.]stripe[.]com/' THEN RAISE EXCEPTION 'invalid_session'; END IF;
  IF c.session_id IS NOT NULL AND c.session_id<>p_session THEN RAISE EXCEPTION 'session_conflict'; END IF;
  UPDATE hocalist.stripe_test_checkouts SET session_id=p_session,session_url=p_url,
   state=CASE WHEN state='creating' THEN 'open' ELSE state END WHERE id=c.id;
 END IF;
END; $$;

-- Caller must have retrieved this exact session and verified Stripe reports expired.
CREATE FUNCTION hocalist.stripe_test_checkout_expire(p_checkout uuid,p_session text,p_customer text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 UPDATE hocalist.stripe_test_checkouts c SET state='expired'
 WHERE c.id=p_checkout AND c.session_id=p_session AND c.state='open'
 AND EXISTS(SELECT 1 FROM hocalist.stripe_test_customers x WHERE x.membership_id=c.membership_id AND x.customer_id=p_customer);
 IF NOT FOUND THEN RAISE EXCEPTION 'checkout_reconciliation_required'; END IF;
END; $$;

-- One global worker lease deliberately serializes reconciliation across this small test environment.
-- Fence is checked again on commit; a stale worker can never overwrite a newer refresh.
CREATE FUNCTION hocalist.stripe_test_claim()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE l hocalist.stripe_test_worker_lock%ROWTYPE; e hocalist.stripe_test_inbox%ROWTYPE; t uuid:=gen_random_uuid();
BEGIN
 SELECT * INTO l FROM hocalist.stripe_test_worker_lock WHERE singleton FOR UPDATE;
 IF l.expires_at>clock_timestamp() THEN RETURN NULL; END IF;
 UPDATE hocalist.stripe_test_inbox SET status='quarantined',last_error='attempt_limit'
 WHERE status='pending' AND attempts>=10;
 SELECT * INTO e FROM hocalist.stripe_test_inbox WHERE status='pending' AND available_at<=now()
 ORDER BY received_at,event_id LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 UPDATE hocalist.stripe_test_worker_lock SET token=t,event_id=e.event_id,expires_at=clock_timestamp()+interval '2 minutes' WHERE singleton;
 UPDATE hocalist.stripe_test_inbox SET attempts=attempts+1 WHERE account_id=e.account_id AND event_id=e.event_id;
 RETURN jsonb_build_object('token',t,'event_id',e.event_id,'event_type',e.event_type,'object_id',e.object_id);
END; $$;

CREATE FUNCTION hocalist.stripe_test_customer_context(p_customer text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('membership_id',c.membership_id,'plans',
  (SELECT jsonb_agg(jsonb_build_object('code',code,'price_id',price_id,'amount_minor',amount_minor)) FROM hocalist.stripe_test_plans),
  'checkouts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'session_id',session_id,'plan_code',plan_code,'price_id',price_id,'amount_minor',amount_minor)), '[]'::jsonb)
    FROM hocalist.stripe_test_checkouts WHERE membership_id=c.membership_id))
 FROM hocalist.stripe_test_customers c WHERE c.customer_id=p_customer;
$$;

CREATE FUNCTION hocalist.stripe_test_finish(p_token uuid,p_event text,p_customer text,p_snapshot jsonb,p_error text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE l hocalist.stripe_test_worker_lock%ROWTYPE; e hocalist.stripe_test_inbox%ROWTYPE; m uuid;
BEGIN
 SELECT * INTO l FROM hocalist.stripe_test_worker_lock WHERE singleton FOR UPDATE;
 IF p_token IS NULL OR l.token IS DISTINCT FROM p_token OR l.event_id IS DISTINCT FROM p_event
  OR l.expires_at IS NULL OR l.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'worker_lease_lost'; END IF;
 SELECT * INTO STRICT e FROM hocalist.stripe_test_inbox WHERE account_id='acct_1Le6hqDmHEV44E5Y' AND event_id=p_event FOR UPDATE;
 IF p_error IS NOT NULL THEN
  -- Fail closed for an owned customer even when an ambiguous provider snapshot cannot be applied.
  IF p_error='review_required' THEN
   UPDATE hocalist.stripe_test_customers SET requires_review=true WHERE customer_id=p_customer;
   UPDATE hocalist.stripe_test_subscriptions SET requires_review=true,updated_at=now()
   WHERE membership_id=(SELECT membership_id FROM hocalist.stripe_test_customers WHERE customer_id=p_customer);
  END IF;
  UPDATE hocalist.stripe_test_inbox SET status=CASE WHEN attempts>=10 OR p_error='review_required' THEN 'quarantined' ELSE 'pending' END,
   available_at=now()+make_interval(secs=>least(3600,30*power(2,least(attempts,7)))::integer),
   last_error=CASE WHEN p_error='review_required' THEN p_error ELSE 'provider_or_storage_unavailable' END
   WHERE account_id=e.account_id AND event_id=e.event_id;
 ELSE
  SELECT membership_id INTO m FROM hocalist.stripe_test_customers WHERE customer_id=p_customer;
  IF m IS NOT NULL AND p_snapshot IS NOT NULL THEN
   IF jsonb_typeof(p_snapshot) IS DISTINCT FROM 'object' OR coalesce(p_snapshot->>'subscription_id','') !~ '^sub_[A-Za-z0-9]+$'
    OR coalesce(p_snapshot->>'status','') NOT IN ('active','trialing','past_due','canceled','incomplete','incomplete_expired','unpaid','paused')
    OR jsonb_typeof(p_snapshot->'cancel_at_period_end') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(p_snapshot->'requires_review') IS DISTINCT FROM 'boolean'
    OR NOT EXISTS(SELECT 1 FROM hocalist.stripe_test_checkouts c WHERE c.membership_id=m
      AND c.id::text=p_snapshot->>'checkout_id' AND c.plan_code=p_snapshot->>'plan_code')
    THEN RAISE EXCEPTION 'invalid_subscription_snapshot'; END IF;
   INSERT INTO hocalist.stripe_test_subscriptions(membership_id,subscription_id,plan_code,provider_status,paid_until,cancel_at_period_end,requires_review)
   VALUES(m,p_snapshot->>'subscription_id',p_snapshot->>'plan_code',p_snapshot->>'status',
    (p_snapshot->>'paid_until')::timestamptz,(p_snapshot->>'cancel_at_period_end')::boolean,(p_snapshot->>'requires_review')::boolean)
   ON CONFLICT(membership_id) DO UPDATE SET subscription_id=excluded.subscription_id,plan_code=excluded.plan_code,
    provider_status=excluded.provider_status,paid_until=excluded.paid_until,cancel_at_period_end=excluded.cancel_at_period_end,
    requires_review=excluded.requires_review OR hocalist.stripe_test_subscriptions.requires_review,updated_at=now();
   UPDATE hocalist.stripe_test_checkouts SET state='complete' WHERE membership_id=m AND id=(p_snapshot->>'checkout_id')::uuid;
  END IF;
  UPDATE hocalist.stripe_test_inbox SET status='processed',last_error=NULL WHERE account_id=e.account_id AND event_id=e.event_id;
 END IF;
 UPDATE hocalist.stripe_test_worker_lock SET token=NULL,event_id=NULL,expires_at=NULL WHERE singleton;
END; $$;

CREATE FUNCTION hocalist.stripe_test_billing_status()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('membership_id',m.id,'plan',CASE WHEN m.status='active'
  AND NOT EXISTS(SELECT 1 FROM hocalist.memberships other WHERE other.user_id=m.user_id AND other.status IN ('restricted','disabled'))
  AND NOT EXISTS(SELECT 1 FROM hocalist.stripe_test_customers c WHERE c.membership_id=m.id AND c.requires_review)
  AND s.provider_status='active' AND s.plan_code IS NOT NULL AND s.paid_until>now() AND NOT s.requires_review THEN s.plan_code ELSE 'free' END,
  'provider_status',s.provider_status,'paid_until',s.paid_until,'cancel_at_period_end',s.cancel_at_period_end,
  'requires_review',coalesce(s.requires_review,false) OR EXISTS(SELECT 1 FROM hocalist.stripe_test_customers c WHERE c.membership_id=m.id AND c.requires_review),'updated_at',s.updated_at)
 FROM hocalist.memberships m LEFT JOIN hocalist.stripe_test_subscriptions s ON s.membership_id=m.id
 WHERE m.user_id=(SELECT auth.uid()) AND m.role='seller';
$$;
REVOKE ALL ON FUNCTION hocalist.stripe_test_checkout_begin(uuid,text,uuid),
 hocalist.stripe_test_checkout_bind(uuid,text,text,text),hocalist.stripe_test_claim(),
 hocalist.stripe_test_checkout_expire(uuid,text,text),
 hocalist.stripe_test_customer_context(text),hocalist.stripe_test_finish(uuid,text,text,jsonb,text),
 hocalist.stripe_test_billing_status() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION hocalist.stripe_test_checkout_begin(uuid,text,uuid),
 hocalist.stripe_test_checkout_bind(uuid,text,text,text),hocalist.stripe_test_claim(),
 hocalist.stripe_test_checkout_expire(uuid,text,text),
 hocalist.stripe_test_customer_context(text),hocalist.stripe_test_finish(uuid,text,text,jsonb,text) TO service_role;
GRANT EXECUTE ON FUNCTION hocalist.stripe_test_billing_status() TO authenticated;

-- DRAFT, not deployed. Requires reviewed membership foundation 003.
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TABLE hocalist.push_devices (
 id uuid PRIMARY KEY,
 user_id uuid NOT NULL REFERENCES hocalist.profiles(id),
 installation_secret_hash text NOT NULL,
 token text UNIQUE NOT NULL CHECK(length(token) BETWEEN 20 AND 4096),
 platform text NOT NULL CHECK(platform='android'),
 enabled boolean NOT NULL,
 revision bigint NOT NULL DEFAULT 1,
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE hocalist.notifications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 user_id uuid NOT NULL REFERENCES hocalist.profiles(id),
 event_key uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN ('new_offer','new_message','meeting_update','billing_update','account_update')),
 source_id uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 read_at timestamptz,
 UNIQUE(user_id,event_key)
);
CREATE TABLE hocalist.push_deliveries (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 notification_id uuid NOT NULL REFERENCES hocalist.notifications(id),
 device_id uuid NOT NULL REFERENCES hocalist.push_devices(id),
 device_revision bigint NOT NULL,
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','accepted','skipped','failed')),
 attempts integer NOT NULL DEFAULT 0,
 available_at timestamptz NOT NULL DEFAULT now(),
 lease_token uuid, lease_until timestamptz,
 last_error text,
 UNIQUE(notification_id,device_id,device_revision)
);
ALTER TABLE hocalist.push_devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE hocalist.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE hocalist.push_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.push_devices,hocalist.notifications,hocalist.push_deliveries FROM PUBLIC,anon,authenticated,service_role;
CREATE POLICY own_notification_read ON hocalist.notifications FOR SELECT TO authenticated USING(
 user_id=(SELECT auth.uid())
 AND EXISTS(SELECT 1 FROM hocalist.memberships m WHERE m.user_id=notifications.user_id AND m.status='active')
 AND NOT EXISTS(SELECT 1 FROM hocalist.memberships m WHERE m.user_id=notifications.user_id AND m.status IN ('restricted','disabled'))
);
GRANT SELECT ON hocalist.notifications TO authenticated;

-- Caller creates a random 256-bit installation secret, retained in device secure storage.
-- Knowing an FCM token or another installation UUID is insufficient to reassign that device.
CREATE FUNCTION hocalist.push_device_register(p_id uuid,p_secret text,p_token text,p_enabled boolean)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid:=auth.uid(); d hocalist.push_devices%ROWTYPE; h text; r bigint;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM hocalist.profiles WHERE id=u FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM hocalist.memberships WHERE user_id=u AND status='active')
 OR EXISTS(SELECT 1 FROM hocalist.memberships WHERE user_id=u AND status IN ('restricted','disabled')) THEN
 RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR coalesce(p_secret,'') !~ '^[a-f0-9]{64}$' OR p_token IS NULL
 OR length(p_token) NOT BETWEEN 20 AND 4096 OR p_enabled IS NULL THEN RAISE EXCEPTION 'invalid_device' USING ERRCODE='22023'; END IF;
 h:=encode(sha256(convert_to(p_secret,'UTF8')),'hex');
 SELECT * INTO d FROM hocalist.push_devices WHERE id=p_id FOR UPDATE;
 IF FOUND THEN
  IF d.installation_secret_hash<>h THEN RAISE EXCEPTION 'device_access_denied' USING ERRCODE='42501'; END IF;
  IF d.user_id=u AND d.token=p_token AND d.enabled=p_enabled THEN
   UPDATE hocalist.push_devices SET updated_at=now() WHERE id=p_id; RETURN d.revision;
  END IF;
 END IF;
 IF (d.id IS NULL OR d.user_id<>u) AND (SELECT count(*) FROM hocalist.push_devices WHERE user_id=u)>=10 THEN
  RAISE EXCEPTION 'device_limit' USING ERRCODE='22023'; END IF;
 IF d.id IS NULL THEN
  INSERT INTO hocalist.push_devices(id,user_id,installation_secret_hash,token,platform,enabled)
  VALUES(p_id,u,h,p_token,'android',p_enabled) RETURNING revision INTO r;
 ELSE
  UPDATE hocalist.push_devices SET user_id=u,token=p_token,enabled=p_enabled,revision=revision+1,updated_at=now()
  WHERE id=p_id RETURNING revision INTO r;
  UPDATE hocalist.push_deliveries SET status='skipped',lease_token=NULL,lease_until=NULL
  WHERE device_id=p_id AND status IN ('pending','sending');
 END IF;
 RETURN r;
END; $$;

CREATE FUNCTION hocalist.push_device_disable(p_id uuid,p_secret text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
 UPDATE hocalist.push_devices SET enabled=false,revision=revision+1,updated_at=now()
 WHERE id=p_id AND user_id=auth.uid() AND installation_secret_hash=encode(sha256(convert_to(p_secret,'UTF8')),'hex');
 IF NOT FOUND THEN RAISE EXCEPTION 'device_access_denied' USING ERRCODE='42501'; END IF;
 UPDATE hocalist.push_deliveries SET status='skipped',lease_token=NULL,lease_until=NULL
 WHERE device_id=p_id AND status IN ('pending','sending');
END; $$;

-- Trusted business-event producers only. Must authorize recipient/source before calling.
-- There is no client-facing enqueue endpoint. No production producer is wired yet.
CREATE FUNCTION hocalist.notification_enqueue(p_user uuid,p_event uuid,p_kind text,p_source uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE n hocalist.notifications%ROWTYPE;
BEGIN
 INSERT INTO hocalist.notifications(user_id,event_key,kind,source_id) VALUES(p_user,p_event,p_kind,p_source)
 ON CONFLICT(user_id,event_key) DO NOTHING;
 SELECT * INTO STRICT n FROM hocalist.notifications WHERE user_id=p_user AND event_key=p_event;
 IF n.kind<>p_kind OR n.source_id<>p_source THEN RAISE EXCEPTION 'notification_event_conflict'; END IF;
 INSERT INTO hocalist.push_deliveries(notification_id,device_id,device_revision)
 SELECT n.id,d.id,d.revision FROM hocalist.push_devices d WHERE d.user_id=p_user AND d.enabled
 AND d.updated_at>now()-interval '30 days' ON CONFLICT DO NOTHING;
 RETURN n.id;
END; $$;

CREATE FUNCTION hocalist.push_claim()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE q hocalist.push_deliveries%ROWTYPE; t uuid:=gen_random_uuid();
BEGIN
 UPDATE hocalist.push_deliveries SET status='failed',last_error='attempt_limit' WHERE attempts>=8
 AND (status='pending' OR (status='sending' AND lease_until<clock_timestamp()));
 SELECT * INTO q FROM hocalist.push_deliveries WHERE attempts<8 AND available_at<=now()
 AND (status='pending' OR (status='sending' AND lease_until<clock_timestamp()))
 ORDER BY available_at,id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL; END IF;
 UPDATE hocalist.push_deliveries SET status='sending',attempts=attempts+1,lease_token=t,lease_until=clock_timestamp()+interval '90 seconds' WHERE id=q.id;
 RETURN jsonb_build_object('id',q.id,'lease',t);
END; $$;

CREATE FUNCTION hocalist.push_delivery_target(p_id uuid,p_lease uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('token',d.token,'notification_id',n.id)
 FROM hocalist.push_deliveries q JOIN hocalist.push_devices d ON d.id=q.device_id
 JOIN hocalist.notifications n ON n.id=q.notification_id
 WHERE q.id=p_id AND q.lease_token=p_lease AND q.status='sending' AND q.lease_until>clock_timestamp()
 AND d.user_id=n.user_id AND d.revision=q.device_revision AND d.enabled AND d.updated_at>now()-interval '30 days'
 AND EXISTS(SELECT 1 FROM hocalist.memberships m WHERE m.user_id=n.user_id AND m.status='active')
 AND NOT EXISTS(SELECT 1 FROM hocalist.memberships m WHERE m.user_id=n.user_id AND m.status IN ('restricted','disabled'));
$$;

CREATE FUNCTION hocalist.push_finish(p_id uuid,p_lease uuid,p_outcome text,p_retry_seconds integer DEFAULT 60)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE q hocalist.push_deliveries%ROWTYPE; d uuid;
BEGIN
 -- Same device -> delivery lock order as registration/logout, avoiding a deadlock cycle.
 SELECT device_id INTO STRICT d FROM hocalist.push_deliveries WHERE id=p_id;
 PERFORM 1 FROM hocalist.push_devices WHERE id=d FOR UPDATE;
 SELECT * INTO STRICT q FROM hocalist.push_deliveries WHERE id=p_id FOR UPDATE;
 IF p_lease IS NULL OR q.lease_token IS DISTINCT FROM p_lease OR q.status<>'sending' OR q.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'push_lease_lost'; END IF;
 IF p_outcome IS NULL OR p_outcome NOT IN ('accepted','skipped','unregistered','retry','configuration_error') THEN RAISE EXCEPTION 'invalid_push_outcome'; END IF;
 UPDATE hocalist.push_deliveries SET status=CASE WHEN p_outcome='accepted' THEN 'accepted' WHEN p_outcome='skipped' THEN 'skipped'
 WHEN p_outcome='retry' AND attempts<8 THEN 'pending' ELSE 'failed' END,
 available_at=now()+make_interval(secs=>greatest(60,least(86400,coalesce(p_retry_seconds,60)))),
 lease_token=NULL,lease_until=NULL,last_error=CASE WHEN p_outcome IN ('accepted','skipped') THEN NULL ELSE p_outcome END WHERE id=p_id;
 IF p_outcome='unregistered' THEN
  UPDATE hocalist.push_devices SET enabled=false,revision=revision+1 WHERE id=q.device_id AND revision=q.device_revision;
 END IF;
END; $$;
REVOKE ALL ON FUNCTION hocalist.push_device_register(uuid,text,text,boolean),hocalist.push_device_disable(uuid,text),
 hocalist.notification_enqueue(uuid,uuid,text,uuid),hocalist.push_claim(),hocalist.push_delivery_target(uuid,uuid),
 hocalist.push_finish(uuid,uuid,text,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION hocalist.push_device_register(uuid,text,text,boolean),hocalist.push_device_disable(uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION hocalist.notification_enqueue(uuid,uuid,text,uuid),hocalist.push_claim(),
 hocalist.push_delivery_target(uuid,uuid),hocalist.push_finish(uuid,uuid,text,integer) TO service_role;

DO $hocalist_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_function constant text := 'hocalist.account_command(text,text,jsonb)';
  v_receipt_function constant text := 'hocalist.receive_stripe_test_event(text,text,text,text,bigint,boolean)';
  v_roles constant text[] := ARRAY['anon', 'authenticated', 'service_role'];
  v_privileges constant text[] := ARRAY[
    'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'];
  -- Predicates are sourced from drafts 003 and compared after lowercasing,
  -- removing whitespace, the pg_get_expr "AS uid" alias and ::text casts.
  v_expected_membership_qual constant text :=
    '(user_id=(selectauth.uid()))';
  v_expected_profile_qual constant text :=
    '(exists(select1fromhocalist.membershipsmwhere((m.id=role_profiles.membership_id)and(m.user_id=(selectauth.uid()))and(m.status=''active''))))';
  v_expected_contact_qual constant text :=
    '((user_id=(selectauth.uid()))and(exists(select1fromhocalist.membershipsmwhere((m.user_id=(selectauth.uid()))and(m.status=''active'')))))';
  v_expected_memberships constant text[] := ARRAY[
    'id:uuid', 'user_id:uuid', 'role:text', 'status:text', 'revision:bigint',
    'created_at:timestamp with time zone', 'updated_at:timestamp with time zone'];
  v_expected_role_profiles constant text[] := ARRAY[
    'membership_id:uuid', 'display_name:text', 'area_label:text', 'profile_note:text',
    'preferred_meetup_type:text', 'service_radius_miles:integer', 'pickup_availability:text',
    'revision:bigint', 'created_at:timestamp with time zone', 'updated_at:timestamp with time zone'];
  v_expected_profile_contacts constant text[] := ARRAY[
    'user_id:uuid', 'phone:text', 'address_line1:text', 'address_line2:text', 'city:text',
    'region:text', 'postal_code:text', 'country_code:text', 'revision:bigint',
    'created_at:timestamp with time zone', 'updated_at:timestamp with time zone'];
  v_expected_receipts constant text[] := ARRAY[
    'user_id:uuid', 'operation:text', 'idempotency_key:text', 'request_hash:text',
    'result:jsonb', 'created_at:timestamp with time zone'];
  v_account_tables constant text[] := ARRAY[
    'memberships', 'role_profiles', 'profile_contacts'];
  v_preserved_relations constant text[] := ARRAY['profiles', 'stripe_test_inbox'];
  v_table text;
  v_role text;
  v_priv text;
  v_columns text[];
  v_policy record;
  v_norm text;
BEGIN
  FOREACH v_table IN ARRAY v_account_tables || ARRAY['command_receipts'] LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'missing table: ' || v_table);
    ELSIF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = ('hocalist.' || v_table)::regclass) THEN
      v_issues := array_append(v_issues, 'row level security disabled: ' || v_table);
    END IF;
  END LOOP;

  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.memberships'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_memberships THEN
    v_issues := array_append(v_issues, 'memberships columns differ from the adapter allowlist');
  END IF;
  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.role_profiles'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_role_profiles THEN
    v_issues := array_append(v_issues, 'role_profiles columns differ from the adapter allowlist');
  END IF;
  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.profile_contacts'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_profile_contacts THEN
    v_issues := array_append(v_issues, 'profile_contacts columns differ from the adapter allowlist');
  END IF;
  SELECT array_agg(attname || ':' || format_type(atttypid, atttypmod) ORDER BY attnum) INTO v_columns
  FROM pg_attribute
  WHERE attrelid = 'hocalist.command_receipts'::regclass AND attnum > 0 AND NOT attisdropped;
  IF v_columns IS DISTINCT FROM v_expected_receipts THEN
    v_issues := array_append(v_issues, 'command_receipts columns differ from the reviewed shape');
  END IF;

  -- Policy set, attributes and full predicates. Name/role/command checks alone
  -- do not prove row isolation, so the normalized predicate is compared too.
  IF (SELECT count(*) FROM pg_policies
      WHERE schemaname = 'hocalist' AND tablename = ANY(v_account_tables)) <> 3 THEN
    v_issues := array_append(v_issues, 'unexpected account policy set');
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies
             WHERE schemaname = 'hocalist' AND tablename = ANY(v_preserved_relations)) THEN
    v_issues := array_append(v_issues, 'preserved baseline object gained a policy');
  END IF;
  FOR v_policy IN
    SELECT tablename, policyname, permissive, roles::text[] AS roles, cmd, qual, with_check
    FROM pg_policies
    WHERE schemaname = 'hocalist' AND tablename = ANY(v_account_tables)
  LOOP
    IF v_policy.policyname NOT IN (
      'membership_owner_read', 'active_owner_profile_read', 'active_owner_contact_read') THEN
      v_issues := array_append(v_issues, 'unexpected account policy: ' || v_policy.policyname);
      CONTINUE;
    END IF;
    IF v_policy.permissive <> 'PERMISSIVE'
       OR v_policy.cmd <> 'SELECT'
       OR v_policy.roles <> ARRAY['authenticated']
       OR v_policy.with_check IS NOT NULL THEN
      v_issues := array_append(v_issues, 'policy attributes changed: ' || v_policy.policyname);
    END IF;
    v_norm := regexp_replace(
      regexp_replace(
        regexp_replace(lower(coalesce(v_policy.qual, '')), '\s+', '', 'g'),
        'asuid', '', 'g'),
      '::text', '', 'g');
    IF v_policy.policyname = 'membership_owner_read'
       AND v_norm IS DISTINCT FROM v_expected_membership_qual THEN
      v_issues := array_append(v_issues, 'policy predicate changed: ' || v_policy.policyname);
    ELSIF v_policy.policyname = 'active_owner_profile_read'
       AND v_norm IS DISTINCT FROM v_expected_profile_qual THEN
      v_issues := array_append(v_issues, 'policy predicate changed: ' || v_policy.policyname);
    ELSIF v_policy.policyname = 'active_owner_contact_read'
       AND v_norm IS DISTINCT FROM v_expected_contact_qual THEN
      v_issues := array_append(v_issues, 'policy predicate changed: ' || v_policy.policyname);
    END IF;
  END LOOP;

  -- Account table ACLs: exactly authenticated SELECT without grant option,
  -- no column grants, and no effective privilege beyond that.
  FOREACH v_table IN ARRAY v_account_tables LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
      WHERE c.oid = ('hocalist.' || v_table)::regclass
        AND pg_get_userbyid(a.grantee) <> 'postgres'
        AND NOT (pg_get_userbyid(a.grantee) = 'authenticated'
                 AND a.privilege_type = 'SELECT' AND NOT a.is_grantable)
    ) THEN
      v_issues := array_append(v_issues,
        'hocalist.' || v_table || ' ACL differs from the reviewed authenticated SELECT grant');
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
      WHERE c.oid = ('hocalist.' || v_table)::regclass
        AND pg_get_userbyid(a.grantee) = 'authenticated'
        AND a.privilege_type = 'SELECT' AND NOT a.is_grantable
    ) THEN
      v_issues := array_append(v_issues,
        'authenticated is missing SELECT on hocalist.' || v_table);
    END IF;
    IF EXISTS (
      SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
      WHERE att.attrelid = ('hocalist.' || v_table)::regclass
        AND att.attnum > 0 AND NOT att.attisdropped
    ) THEN
      v_issues := array_append(v_issues,
        'hocalist.' || v_table || ' has unexpected column grants');
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      FOREACH v_priv IN ARRAY v_privileges LOOP
        IF has_table_privilege(v_role, 'hocalist.' || v_table, v_priv)
           IS DISTINCT FROM (v_role = 'authenticated' AND v_priv = 'SELECT') THEN
          v_issues := array_append(v_issues,
            'unexpected ' || v_priv || ' for ' || v_role || ' on hocalist.' || v_table);
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;

  -- Receipts: owner-only ACL, no column grants, no effective client access.
  IF EXISTS (
    SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
    WHERE c.oid = 'hocalist.command_receipts'::regclass
      AND pg_get_userbyid(a.grantee) <> 'postgres'
  ) THEN
    v_issues := array_append(v_issues, 'command_receipts has unexpected non-owner grants');
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
    WHERE att.attrelid = 'hocalist.command_receipts'::regclass
      AND att.attnum > 0 AND NOT att.attisdropped
  ) THEN
    v_issues := array_append(v_issues, 'command_receipts has unexpected column grants');
  END IF;
  FOREACH v_role IN ARRAY v_roles LOOP
    FOREACH v_priv IN ARRAY v_privileges LOOP
      IF has_table_privilege(v_role, 'hocalist.command_receipts', v_priv) THEN
        v_issues := array_append(v_issues,
          'unexpected ' || v_priv || ' for ' || v_role || ' on hocalist.command_receipts');
      END IF;
    END LOOP;
  END LOOP;

  -- account_command: exactly authenticated EXECUTE without grant option.
  IF EXISTS (
    SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
    WHERE p.oid = to_regprocedure(v_function)
      AND pg_get_userbyid(a.grantee) <> 'postgres'
      AND NOT (pg_get_userbyid(a.grantee) = 'authenticated'
               AND a.privilege_type = 'EXECUTE' AND NOT a.is_grantable)
  ) OR EXISTS (
    SELECT 1 FROM pg_proc p WHERE p.oid = to_regprocedure(v_function) AND p.proacl IS NULL
  ) THEN
    v_issues := array_append(v_issues,
      'account_command ACL differs from the reviewed authenticated EXECUTE grant');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
    WHERE p.oid = to_regprocedure(v_function)
      AND pg_get_userbyid(a.grantee) = 'authenticated'
      AND a.privilege_type = 'EXECUTE' AND NOT a.is_grantable
  ) THEN
    v_issues := array_append(v_issues, 'authenticated is missing EXECUTE on account_command');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p
    WHERE p.oid = to_regprocedure(v_function)
      AND p.prosecdef
      AND p.proconfig = ARRAY['search_path=""']
      AND pg_get_userbyid(p.proowner) = 'postgres'
  ) THEN
    v_issues := array_append(v_issues, 'account_command security properties changed');
  END IF;
  FOREACH v_role IN ARRAY v_roles LOOP
    IF has_function_privilege(v_role, v_function, 'EXECUTE')
       IS DISTINCT FROM (v_role = 'authenticated') THEN
      v_issues := array_append(v_issues,
        'unexpected EXECUTE for ' || v_role || ' on account_command');
    END IF;
  END LOOP;

  -- Schema: owner plus authenticated and service_role USAGE only.
  IF EXISTS (
    SELECT 1 FROM pg_namespace n, aclexplode(n.nspacl) a
    WHERE n.nspname = 'hocalist'
      AND NOT (
        pg_get_userbyid(a.grantee) = 'postgres'
        OR (pg_get_userbyid(a.grantee) IN ('authenticated', 'service_role')
            AND a.privilege_type = 'USAGE' AND NOT a.is_grantable)
      )
  ) THEN
    v_issues := array_append(v_issues,
      'hocalist schema ACL differs from the reviewed account grant set');
  END IF;
  IF NOT has_schema_privilege('authenticated', 'hocalist', 'USAGE')
     OR has_schema_privilege('authenticated', 'hocalist', 'CREATE')
     OR has_schema_privilege('anon', 'hocalist', 'USAGE')
     OR has_schema_privilege('anon', 'hocalist', 'CREATE')
     OR NOT has_schema_privilege('service_role', 'hocalist', 'USAGE')
     OR has_schema_privilege('service_role', 'hocalist', 'CREATE') THEN
    v_issues := array_append(v_issues, 'schema privileges are wrong after apply');
  END IF;

  -- Preserved baseline privilege matrix (same rules as the guard).
  FOREACH v_table IN ARRAY v_preserved_relations LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'preserved object missing: hocalist.' || v_table);
    ELSE
      IF EXISTS (
        SELECT 1 FROM pg_class c, aclexplode(c.relacl) a
        WHERE c.oid = ('hocalist.' || v_table)::regclass
          AND pg_get_userbyid(a.grantee) <> 'postgres'
      ) THEN
        v_issues := array_append(v_issues,
          'hocalist.' || v_table || ' has unexpected non-owner grants');
      END IF;
      IF EXISTS (
        SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
        WHERE att.attrelid = ('hocalist.' || v_table)::regclass
          AND att.attnum > 0 AND NOT att.attisdropped
      ) THEN
        v_issues := array_append(v_issues,
          'hocalist.' || v_table || ' has unexpected column grants');
      END IF;
      IF EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'hocalist' AND tablename = v_table
      ) THEN
        v_issues := array_append(v_issues,
          'hocalist.' || v_table || ' has an unexpected policy');
      END IF;
      FOREACH v_role IN ARRAY v_roles LOOP
        FOREACH v_priv IN ARRAY v_privileges LOOP
          IF has_table_privilege(v_role, 'hocalist.' || v_table, v_priv) THEN
            v_issues := array_append(v_issues,
              'unexpected ' || v_priv || ' for ' || v_role || ' on hocalist.' || v_table);
          END IF;
        END LOOP;
      END LOOP;
    END IF;
  END LOOP;

  IF to_regprocedure(v_receipt_function) IS NULL THEN
    v_issues := array_append(v_issues, 'deployed 005 receive_stripe_test_event is missing');
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
      WHERE p.oid = to_regprocedure(v_receipt_function)
        AND NOT (
          pg_get_userbyid(a.grantee) = 'postgres'
          OR (pg_get_userbyid(a.grantee) = 'service_role'
              AND a.privilege_type = 'EXECUTE' AND NOT a.is_grantable)
        )
    ) THEN
      v_issues := array_append(v_issues,
        'receive_stripe_test_event ACL differs from the reviewed 005 state');
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      IF (v_role = 'service_role'
          AND NOT has_function_privilege(v_role, v_receipt_function, 'EXECUTE'))
         OR (v_role <> 'service_role'
          AND has_function_privilege(v_role, v_receipt_function, 'EXECUTE')) THEN
        v_issues := array_append(v_issues,
          'receive_stripe_test_event execution differs for ' || v_role);
      END IF;
    END LOOP;
  END IF;
  IF to_regprocedure('hocalist.handle_new_user()') IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
      WHERE p.oid = to_regprocedure('hocalist.handle_new_user()')
        AND pg_get_userbyid(a.grantee) <> 'postgres'
    ) THEN
      v_issues := array_append(v_issues, 'handle_new_user has unexpected execution grants');
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      IF has_function_privilege(v_role, 'hocalist.handle_new_user()', 'EXECUTE') THEN
        v_issues := array_append(v_issues,
          'unexpected EXECUTE for ' || v_role || ' on handle_new_user');
      END IF;
    END LOOP;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
    WHERE t.tgrelid = 'auth.users'::regclass
      AND t.tgname = 'on_auth_user_created'
      AND t.tgfoid = to_regprocedure('hocalist.handle_new_user()')
      AND t.tgenabled = 'O'
  ) THEN
    v_issues := array_append(v_issues, 'signup routing trigger changed');
  END IF;

  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist post-apply verification failed: %', array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_postapply$;
DO $provider_verify$
DECLARE t text; r text; p text; f record; allowed_role text;
BEGIN
 FOREACH t IN ARRAY ARRAY['stripe_test_plans','stripe_test_customers','stripe_test_checkouts','stripe_test_subscriptions','stripe_test_worker_lock','push_devices','notifications','push_deliveries'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('hocalist.'||t) AND relrowsecurity AND relowner='postgres'::regrole) THEN
   RAISE EXCEPTION 'Provider table owner/RLS mismatch: %',t; END IF;
  IF EXISTS(SELECT 1 FROM pg_class c,aclexplode(c.relacl) a WHERE c.oid=to_regclass('hocalist.'||t)
   AND NOT(a.grantee='postgres'::regrole OR(t='notifications' AND a.grantee='authenticated'::regrole AND a.privilege_type='SELECT' AND NOT a.is_grantable))) THEN
   RAISE EXCEPTION 'Provider table ACL mismatch: %',t; END IF;
  IF EXISTS(SELECT 1 FROM pg_attribute a,aclexplode(a.attacl) x WHERE a.attrelid=to_regclass('hocalist.'||t) AND x.grantee<>'postgres'::regrole) THEN
   RAISE EXCEPTION 'Unexpected provider column grant: %',t; END IF;
  FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   FOREACH p IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
    IF has_table_privilege(r,'hocalist.'||t,p) IS DISTINCT FROM (t='notifications' AND r='authenticated' AND p='SELECT') THEN
     RAISE EXCEPTION 'Unexpected provider permission: % % %',t,r,p; END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 IF (SELECT count(*) FROM pg_policy WHERE polrelid='hocalist.notifications'::regclass)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='hocalist.notifications'::regclass AND polname='own_notification_read'
  AND polcmd='r' AND polpermissive AND polroles=ARRAY['authenticated'::regrole::oid] AND polwithcheck IS NULL
  AND md5(pg_get_expr(polqual,polrelid))='b29f9d33454f4464ad0d1df1486aaf69') THEN RAISE EXCEPTION 'Notification policy mismatch'; END IF;
 FOR f IN SELECT * FROM (VALUES
 ('hocalist.notification_enqueue(uuid,uuid,text,uuid)','ce9fe8b53787f218be794206deb9b4ee','service_role'),
 ('hocalist.push_claim()','b03572856ee85a8b44cf25c974447769','service_role'),
 ('hocalist.push_delivery_target(uuid,uuid)','4cb8c3d0df011f98c730a7d491a694a9','service_role'),
 ('hocalist.push_device_disable(uuid,text)','b83ac1d7f4d40e36337a6ba2439dde3e','authenticated'),
 ('hocalist.push_device_register(uuid,text,text,boolean)','3f16426321e84d08eb8016c0f04d1d28','authenticated'),
 ('hocalist.push_finish(uuid,uuid,text,integer)','11c1a677253561b798f889301e240b6a','service_role'),
 ('hocalist.stripe_test_billing_status()','9f187a6c93e9eaa8f4c843548f3987ff','authenticated'),
 ('hocalist.stripe_test_checkout_begin(uuid,text,uuid)','8b31107c499f9cb50fb0ab5996b2fa3a','service_role'),
 ('hocalist.stripe_test_checkout_bind(uuid,text,text,text)','408b9084dd5c322af60691177bbe9ebe','service_role'),
 ('hocalist.stripe_test_checkout_expire(uuid,text,text)','259ef6a9a81c2643cd92eda43cc350c9','service_role'),
 ('hocalist.stripe_test_claim()','14d7aa63e072dc8e2c9c935fc6793393','service_role'),
 ('hocalist.stripe_test_customer_context(text)','f652b2bbb9f8256512a14a4cb439ffc7','service_role'),
 ('hocalist.stripe_test_finish(uuid,text,text,jsonb,text)','492c607acaceaf0e47ee3026cd55f957','service_role')
 ) AS expected(signature,digest,grantee) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure(f.signature) AND prosecdef AND proowner='postgres'::regrole
   AND md5(replace(pg_get_functiondef(oid),chr(13),''))=f.digest AND proacl IS NOT NULL) THEN RAISE EXCEPTION 'Provider function mismatch: %',f.signature; END IF;
  IF EXISTS(SELECT 1 FROM pg_proc q,aclexplode(q.proacl) a WHERE q.oid=to_regprocedure(f.signature)
   AND NOT(a.grantee='postgres'::regrole OR(a.grantee=f.grantee::regrole AND a.privilege_type='EXECUTE' AND NOT a.is_grantable))) THEN
   RAISE EXCEPTION 'Provider function ACL mismatch: %',f.signature; END IF;
  FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   IF has_function_privilege(r,f.signature,'EXECUTE') IS DISTINCT FROM (r=f.grantee) THEN
    RAISE EXCEPTION 'Unexpected provider execution permission: % %',f.signature,r; END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM hocalist.stripe_test_plans WHERE enabled) THEN RAISE EXCEPTION 'Plans must stay disabled at foundation rollout'; END IF;
END;
$provider_verify$;
COMMIT;
SELECT 'PASS: provider foundation applied; plans disabled; no schedules created' AS provider_rollout;
